                    ['question' => 'Why might a client score well on the WAB-R Aphasia Quotient but still struggle in daily communication?', 'options' => [['text' => 'Standardized scores do not fully capture functional, real-world communicative effectiveness', 'correct' => true], ['text' => 'The WAB-R is not a validated tool', 'correct' => false], ['text' => 'Functional communication always matches test performance exactly', 'correct' => false], ['text' => 'The Aphasia Quotient measures only motor speech skills', 'correct' => false]], 'explanation' => 'Functional measures like the Communicative Effectiveness Index assess real-world performance, which can diverge from structured test performance.'],
                    ['question' => 'Why is it important to screen for apraxia of speech during an aphasia assessment?', 'options' => [['text' => 'It frequently co-occurs with aphasia after left-hemisphere stroke and requires distinct treatment', 'correct' => true], ['text' => 'Apraxia of speech only occurs in children', 'correct' => false], ['text' => 'It rules out the need for any language testing', 'correct' => false], ['text' => 'It is not relevant to post-stroke clients', 'correct' => false]], 'explanation' => 'Apraxia of speech, a motor speech planning disorder, commonly co-occurs with aphasia due to shared vascular territory and needs a differentiated treatment approach.'],
                ]]],
